    } catch (Throwable t) // PATH: Test should invoke the next Log4j2LoggerImpl.warn(...) [step in execution path]
    {
        log.warn(((((("Could not examine class '" + fqn) + "'") + " due to a ") + t.getClass().getName()) + " with message: ") + t.getMessage());
